#!/usr/bin/env python3
"""Probe what PDF/image libraries and CLI tools exist in this environment."""
import importlib
import shutil

modules = [
    "PIL", "numpy", "matplotlib", "fpdf", "img2pdf", "weasyprint",
    "cairosvg", "svglib", "lxml", "reportlab", "fitz", "borb", "pydyf",
]

print("--- Python modules ---")
for name in modules:
    try:
        mod = importlib.import_module(name)
        version = getattr(mod, "__version__", "unknown")
        print(f"OK    {name} (version={version})")
    except Exception as exc:
        print(f"MISS  {name} ({type(exc).__name__})")

print("--- CLI tools ---")
for tool in ["qpdf", "pdftk", "pdftotext", "pdfinfo", "gs", "mutool", "python3", "pip", "pip3"]:
    path = shutil.which(tool)
    print(f"{tool}: {path if path else 'not found'}")

#!/usr/bin/env python3
"""Debug: dump the parsed structure of report.pdf."""
import re
import sys

sys.path.insert(0, ".")
# Reuse functions from add_cover_std by exec'ing its top portion is messy;
# instead inline a minimal copy of the parser here.
WS = b" \t\r\n\0\f"
DELIMS = b"()<>[]{}/%"


def tokenize(data):
    tokens = []
    i, n = 0, len(data)
    while i < n:
        b = data[i:i + 1]
        if b in WS:
            i += 1
            continue
        if b == b"%":
            while i < n and data[i:i + 1] not in (b"\r", b"\n"):
                i += 1
            continue
        if b == b"(":
            start, depth = i, 1
            i += 1
            while i < n and depth:
                c = data[i:i + 1]
                if c == b"\\":
                    i += 2
                    continue
                if c == b"(":
                    depth += 1
                elif c == b")":
                    depth -= 1
                i += 1
            tokens.append(("lit", data[start:i]))
            continue
        if b == b"<":
            if data[i:i + 2] == b"<<":
                tokens.append(("kw", "<<"))
                i += 2
                continue
            j = data.find(b">", i)
            tokens.append(("hex", data[i:j + 1]))
            i = j + 1
            continue
        if b == b">":
            tokens.append(("kw", ">>"))
            i += 1
            continue
        if b == b"[":
            tokens.append(("kw", "["))
            i += 1
            continue
        if b == b"]":
            tokens.append(("kw", "]"))
            i += 1
            continue
        if b == b"/":
            j = i + 1
            while j < n and data[j:j + 1] not in WS and data[j:j + 1] not in DELIMS:
                j += 1
            tokens.append(("name", data[i:j]))
            i = j
            continue
        j = i
        while j < n and data[j:j + 1] not in WS and data[j:j + 1] not in DELIMS:
            j += 1
        raw = data[i:j]
        i = j
        if re.fullmatch(rb"[+-]?(\d+\.?\d*|\.\d+)", raw):
            tokens.append(("num", float(raw) if b"." in raw else int(raw)))
        else:
            tokens.append(("kw", raw.decode("latin-1")))
    return tokens


def parse_value(tokens, i):
    kind, val = tokens[i]
    if kind == "kw":
        if val == "<<":
            d = {}
            i += 1
            while tokens[i][1] != ">>":
                key = tokens[i][1].decode("latin-1")
                i += 1
                v, i = parse_value(tokens, i)
                d[key] = v
            return d, i + 1
        if val == "[":
            arr = []
            i += 1
            while tokens[i][1] != "]":
                v, i = parse_value(tokens, i)
                arr.append(v)
            return arr, i + 1
        if val == "true":
            return True, i + 1
        if val == "false":
            return False, i + 1
        if val == "null":
            return None, i + 1
        raise ValueError(f"unexpected keyword: {val}")
    if kind == "num":
        if (i + 2 < len(tokens) and tokens[i + 1][0] == "num"
                and tokens[i + 2] == ("kw", "R")):
            return (int(val), int(tokens[i + 1][1])), i + 3
        return val, i + 1
    if kind == "name":
        return val, i + 1
    if kind == "lit":
        return val, i + 1
    if kind == "hex":
        return val, i + 1
    raise ValueError(f"cannot parse token: {tokens[i]}")


def parse_xref(data, xref_off):
    entries = {}
    pos = xref_off
    m = re.match(rb"xref\s+", data[pos:])
    pos += m.end()
    while True:
        m = re.match(rb"(\d+)\s+(\d+)\s+", data[pos:])
        if not m:
            break
        start, count = int(m.group(1)), int(m.group(2))
        pos += m.end()
        for k in range(count):
            line = data[pos:pos + 20]
            off = int(line[0:10])
            gen = int(line[11:16])
            free = line[17:18] == b"f"
            entries[start + k] = (off, gen, free)
            pos += 20
    m = re.search(rb"trailer\s*(<<.*?>>)", data[pos:], re.S)
    toks = tokenize(m.group(1))
    trailer, _ = parse_value(toks, 0)
    return entries, trailer


def read_object(data, offset):
    end = data.find(b"endobj", offset)
    raw = data[offset:end]
    s = raw.find(b"stream")
    if s != -1:
        toks = tokenize(raw[:s])
        val, _ = parse_value(toks, 3)
    else:
        toks = tokenize(raw)
        val, _ = parse_value(toks, 3)
    return val, raw


data = open("report.pdf", "rb").read()
m = re.findall(rb"startxref\s+(\d+)", data)
entries, trailer = parse_xref(data, int(m[-1]))
print("entries:", entries)
root = read_object(data, entries[trailer["/Root"][0]][0])[0]
print("root:", root)
pages = read_object(data, entries[root["/Pages"][0]][0])[0]
print("pages:", pages)
for kid in pages["/Kids"]:
    if isinstance(kid, tuple):
        print("kid ref:", kid)
        obj, raw = read_object(data, entries[kid[0]][0])
        print("kid object:", obj)
    else:
        print("kid NOT a ref:", repr(kid))

